+    /**
+     * Resolves an archive entry name against the destination directory and makes sure that the
+     * resulting path does not escape that directory (aka "Zip Slip", CWE-22).
+     *
+     * @param dest the directory the archive is extracted into
+     * @param name the name of the archive entry
+     * @return the canonicalized destination file of the entry
+     * @throws IOException if the entry would be extracted outside of {@code dest}
+     */
+    private static File validateArchiveEntry(File dest, String name) throws IOException {
+        if (name == null || name.isEmpty()) {
+            throw new IOException("Invalid archive entry: empty entry name.");
+        }
+
+        File destDir = dest.getCanonicalFile();
+        File file = new File(destDir, name).getCanonicalFile();
+
+        String destPath = destDir.getPath();
+        String filePath = file.getPath();
+        if (!filePath.equals(destPath)
+                && !filePath.startsWith(destPath + File.separator)) {
+            throw new IOException(
+                    "Invalid archive entry, entry is outside of the target directory: " + name);
+        }
+
+        return file;
+    }
 }

