+/**
+ * Validates endpoint URLs which are used to fetch pipeline element descriptions.
+ * Only URLs which point to an extensions service that is currently registered at the
+ * service discovery are considered valid. This prevents server-side request forgery (SSRF),
+ * since otherwise arbitrary user-provided addresses would be called by the core.
+ */
+public class EndpointUrlValidator {
+
+  private static final List<String> SUPPORTED_SCHEMES = List.of("http", "https");
+
+  /**
+   * Checks whether the given endpoint URL belongs to a registered StreamPipes extensions service.
+   *
+   * @param endpointUrl the endpoint URL provided by a user
+   * @return true if the URL points to a registered extensions service, false otherwise
+   */
+  public boolean isRegisteredExtensionsServiceEndpoint(String endpointUrl) {
+    if (endpointUrl == null || endpointUrl.isBlank()) {
+      return false;
+    }
+
+    var requestedAuthority = extractAuthority(endpointUrl);
+    if (requestedAuthority == null) {
+      return false;
+    }
+
+    return getRegisteredExtensionsServices()
+        .stream()
+        .map(this::extractAuthority)
+        .filter(Objects::nonNull)
+        .anyMatch(requestedAuthority::equals);
+  }
+
+  private List<String> getRegisteredExtensionsServices() {
+    return SpServiceDiscovery
+        .getServiceDiscovery()
+        .getServiceEndpoints(DefaultSpServiceGroups.EXT, true, Collections.emptyList());
+  }
+
+  /**
+   * Extracts a normalized {@code host:port} representation of the given URL.
+   *
+   * @return the normalized authority or null if the URL is malformed or uses an unsupported scheme
+   */
+  private String extractAuthority(String url) {
+    try {
+      var uri = new URI(url.contains("://") ? url.trim() : "http://" + url.trim());
+      var scheme = uri.getScheme();
+      var host = uri.getHost();
+      if (scheme == null || host == null || host.isBlank()) {
+        return null;
+      }
+      if (!SUPPORTED_SCHEMES.contains(scheme.toLowerCase(Locale.ROOT))) {
+        return null;
+      }
+      return host.toLowerCase(Locale.ROOT) + ":" + uri.getPort();
+    } catch (URISyntaxException e) {
+      return null;
+    }
+  }
+}
